const data = [
  { name: "Product A", value: 65 },
  { name: "Product B", value: 90 },
  { name: "Product C", value: 45 },
  { name: "Product D", value: 75 },
  { name: "Product E", value: 30 },
  { name: "Product F", value: 85 },
  { name: "Product G", value: 55 }
];

const margin = { top: 40, right: 30, bottom: 60, left: 70 };
const width = 900 - margin.left - margin.right;
const height = 500 - margin.top - margin.bottom;

d3.select("body").style("background-color", "#f5f7fa").style("margin", "0").style("padding", "40px");

const svg = d3.select("body")
  .append("svg")
  .attr("width", width + margin.left + margin.right)
  .attr("height", height + margin.top + margin.bottom)
  .style("background-color", "#ffffff")
  .style("border-radius", "8px")
  .style("box-shadow", "0 2px 8px rgba(0,0,0,0.1)")
  .append("g")
  .attr("transform", `translate(${margin.left},${margin.top})`);

const x = d3.scaleBand()
  .domain(data.map(d => d.name))
  .range([0, width])
  .padding(0.35);

const y = d3.scaleLinear()
  .domain([0, d3.max(data, d => d.value) * 1.15])
  .range([height, 0]);

const colorScale = d3.scaleSequential()
  .domain([0, d3.max(data, d => d.value)])
  .interpolator(d3.interpolateBlues);

svg.append("g")
  .attr("class", "grid")
  .call(d3.axisLeft(y)
    .tickSize(-width)
    .tickFormat("")
  )
  .style("stroke-dasharray", "2,2")
  .style("stroke-opacity", 0.15)
  .selectAll("line")
  .style("stroke", "#64748b");

svg.select(".grid").select(".domain").remove();

svg.append("g")
  .attr("transform", `translate(0,${height})`)
  .call(d3.axisBottom(x))
  .selectAll("text")
  .style("font-size", "12px")
  .style("fill", "#475569")
  .style("font-family", "system-ui, sans-serif");

svg.append("g")
  .call(d3.axisLeft(y).ticks(6))
  .style("font-size", "12px")
  .style("fill", "#475569")
  .style("font-family", "system-ui, sans-serif");

svg.selectAll(".domain, .tick line").style("stroke", "#cbd5e1");

svg.append("text")
  .attr("x", width / 2)
  .attr("y", -15)
  .attr("text-anchor", "middle")
  .style("font-size", "18px")
  .style("font-weight", "600")
  .style("fill", "#1e293b")
  .style("font-family", "system-ui, sans-serif")
  .text("Sales Performance by Product");

const bars = svg.selectAll(".bar")
  .data(data)
  .enter()
  .append("rect")
  .attr("class", "bar")
  .attr("x", d => x(d.name))
  .attr("width", x.bandwidth())
  .attr("y", height)
  .attr("height", 0)
  .attr("fill", d => colorScale(d.value))
  .attr("rx", 6)
  .attr("ry", 6)
  .style("cursor", "pointer");

bars.transition()
  .duration(1200)
  .delay((d, i) => i * 100)
  .ease(d3.easeBackOut.overshoot(1.2))
  .attr("y", d => y(d.value))
  .attr("height", d => height - y(d.value));

const labels = svg.selectAll(".label")
  .data(data)
  .enter()
  .append("text")
  .attr("x", d => x(d.name) + x.bandwidth() / 2)
  .attr("y", height)
  .attr("text-anchor", "middle")
  .style("font-size", "13px")
  .style("font-weight", "600")
  .style("fill", "#1e293b")
  .style("font-family", "system-ui, sans-serif")
  .style("opacity", 0)
  .text(d => d.value);

labels.transition()
  .duration(1200)
  .delay((d, i) => i * 100 + 400)
  .ease(d3.easeCubicOut)
  .attr("y", d => y(d.value) - 8)
  .style("opacity", 1);

bars.on("mouseover", function(event, d) {
  d3.select(this)
    .transition()
    .duration(200)
    .attr("fill", "#f97316");
})
.on("mouseout", function(event, d) {
  d3.select(this)
    .transition()
    .duration(200)
    .attr("fill", colorScale(d.value));
});

setTimeout(() => {
  const updatedData = data.map(d => ({
    name: d.name,
    value: Math.floor(Math.random() * 70) + 30
  }));

  y.domain([0, d3.max(updatedData, d => d.value) * 1.15]);

  svg.selectAll("g").filter(function() {
    return d3.select(this).attr("transform") === null && d3.select(this).attr("class") !== "grid";
  }).transition().duration(750).call(d3.axisLeft(y).ticks(6));

  svg.selectAll(".bar")
    .data(updatedData)
    .transition()
    .duration(750)
    .ease(d3.easeCubicInOut)
    .attr("y", d => y(d.value))
    .attr("height", d => height - y(d.value))
    .attr("fill", d => colorScale(d.value));

  svg.selectAll(".label")
    .data(updatedData)
    .transition()
    .duration(750)
    .attr("y", d => y(d.value) - 8)
    .text(d => d.value);
}, 4000);

