  .style("fill", "#1e293b")
  .style("font-family", "system-ui, sans-serif")
  .text("Sales Performance by Product");

const bars = svg.selectAll(".bar")
  .data(data)
  .enter()
  .append("rect")
  .attr("class", "bar")
  .attr("x", d => x(d.name))
  .attr("width", x.bandwidth())
  .attr("y", height)
  .attr("height", 0)
  .attr("fill", d => colorScale(d.value))
  .attr("rx", 6)
  .attr("ry", 6)
  .style("cursor", "pointer");

bars.transition()
  .duration(1200)
  .delay((d, i) => i * 100)
  .ease(d3.easeBackOut.overshoot(1.2))
  .attr("y", d => y(d.value))
  .attr("height", d => height - y(d.value));

const labels = svg.selectAll(".label")
  .data(data)
  .enter()
  .append("text")
  .attr("x", d => x(d.name) + x.bandwidth() / 2)
  .attr("y", height)
  .attr("text-anchor", "middle")
  .style("font-size", "13px")
  .style("font-weight", "600")
  .style("fill", "#1e293b")
  .style("font-family", "system-ui, sans-serif")
  .style("opacity", 0)
  .text(d => d.value);

labels.transition()
  .duration(1200)
  .delay((d, i) => i * 100 + 400)
  .ease(d3.easeCubicOut)
  .attr("y", d => y(d.value) - 8)
  .style("opacity", 1);

bars.on("mouseover", function(event, d) {
  d3.select(this)
    .transition()
    .duration(200)
    .attr("fill", "#f97316");
})
.on("mouseout", function(event, d) {
  d3.select(this)
    .transition()
    .duration(200)
    .attr("fill", colorScale(d.value));
});

setTimeout(() => {
  const updatedData = data.map(d => ({
    name: d.name,
    value: Math.floor(Math.random() * 70) + 30
  }));

  y.domain([0, d3.max(updatedData, d => d.value) * 1.15]);

  svg.selectAll("g").filter(function() {
    return d3.select(this).attr("transform") === null && d3.select(this).attr("class") !== "grid";
  }).transition().duration(750).call(d3.axisLeft(y).ticks(6));

  svg.selectAll(".bar")
    .data(updatedData)
    .transition()
    .duration(750)
    .ease(d3.easeCubicInOut)
    .attr("y", d => y(d.value))
    .attr("height", d => height - y(d.value))
    .attr("fill", d => colorScale(d.value));

  svg.selectAll(".label")
    .data(updatedData)
    .transition()
    .duration(750)
    .attr("y", d => y(d.value) - 8)
    .text(d => d.value);
}, 4000);
